package httpapi

import "github.com/danielgtaylor/huma/v2"

// apiTags is the top-level OpenAPI tag catalog: the ordered, documented list of
// groups the operations sort into. Declaring it here (rather than letting huma
// synthesise bare tags from first use) gives every group a description and a
// deliberate order in the rendered docs. Each operation's own Tags value (set at
// registration, one per operation) must name one of these — grouping tracks the
// resource, independent of the access gate that wired the route.
//
// Order is reader-facing and the renderer follows this slice, so moving an entry
// moves the group in the docs: the caller's own surface, then a repo and its
// sub-resources, then the trail family (roughly the order a trail moves through
// it, with attachments trailing as an ancillary), then cross-repo rollups and
// repo configuration, and last the machine-only groups. Anything more precise
// than that rots the next time a tag is inserted.
//
// Only tags on THIS document belong here. The internal admin surface builds its
// own huma config in NewAdminHandler and never reads apiTags, so declaring its
// tag here would render an empty group.
var apiTags = []*huma.Tag{
	{Name: "me", Description: "The authenticated caller's own cross-repo activity, commits, checkpoints, sessions, and recap."},
	{Name: "experimental", Description: "Residency-aware previews of the caller's surface, served under /experimental. Shapes may change without notice."},
	{Name: "preferences", Description: "Per-user settings: pinned and recent repos, diff view, and saved filter tabs."},
	{Name: "repos", Description: "Repository discovery list, metadata, and headline rollups (summary, activity, contributors, agents)."},
	{Name: "code", Description: "Git browsing for a repo: commits, commit detail, branch compare, tree listings, raw file bytes, and branches."},
	{Name: "checkpoints", Description: "Checkpoint listing, resolution, LLM analysis, transcripts, and per-repo checkpoint status."},
	{Name: "sessions", Description: "Materialised sessions: listing, detail, transcripts, rename, and the public-share toggle."},
	{Name: "overview", Description: "Repo dashboard aggregates under /overview: commit and checkpoint stats, contributor breakdowns, and session patterns."},
	{Name: "refs", Description: "Live ref-change stream for a repo (SSE)."},
	{Name: "trails", Description: "Trails themselves: list, create, read, update, delete, plus per-repo counts, claimed branches, and the body-document ensure."},
	{Name: "trail-activity", Description: "What has happened on a trail: the merged timeline, the event stream, and who is watching (per trail, plus a repo-wide roll-up)."},
	{Name: "trail-threads", Description: "Conversation on a trail: threads, their messages, and the live thread-event stream."},
	{Name: "trail-reviews", Description: "Code review on a trail: review state, comments, diffs, reviewed files, and review re-runs."},
	{Name: "trail-runs", Description: "Runner output on a trail: the latest result per configured runner, monitor results, and manual launches."},
	{Name: "trail-gates", Description: "Quality gates: repo gate definitions, gate settings, repo-authored monitor definitions, and a trail's gate evaluation."},
	{Name: "trail-approvals", Description: "Getting a trail landed: approval decisions, merge readiness, and the merge itself."},
	{Name: "trail-attachments", Description: "Trail attachment blobs: upload intent, completion, retrieval, and deletion."},
	{Name: "projects", Description: "Project-scoped rollups across the project's repos: summary, repos, activity, and contributors."},
	{Name: "experts", Description: "Agent-provenance ranking for a repo's code scopes."},
	{Name: "git-meta", Description: "git-meta-compatible repo metadata read and write (git is the source of truth)."},
	{Name: "records", Description: "Experimental, read-only: schema-described records decoded from a repository's git-meta records store (refs/meta/records/<schema>/main). Shapes may change without notice."},
	{Name: "repo-settings", Description: "Mutating repo configuration: runner, trail, and public-sharing settings (requires repo push; the gate-enforcement toggle requires manage_settings)."},
	{Name: "pull-requests", Description: "The caller's open pull requests across their repositories."},
	{Name: "trails-internal", Description: "Service-authed only: editor-document sync behind the trail body editor. The runner ingest routes carry this tag too, but are hidden from the document."},
