func ProposalID(branch, baseRef, contentRef string) string {
	h := sha256.New()
	writeLenPrefixed(h, branch)
	writeLenPrefixed(h, baseRef)
	writeLenPrefixed(h, contentRef)
	return "prop-" + hex.EncodeToString(h.Sum(nil))
}

